-- Backfill de descripciones de partidas (headings) y subpartidas (subheadings).
-- Fuente: Base Única LIGIE, BASEUNICA-LIGIE_20260330-20260330.xlsb (DOF 2026-03-30),
-- columna "Descripción" VERBATIM (mismo archivo del que se sembraron las fracciones).
-- Motivo: seed-ligie-2026.ts creó estas filas con placeholders ("Partida XXXX" /
-- "Subpartida XXXXXX"); el clasificador (DEFERRED #19) necesita el texto real.
-- Idempotente: UPDATE por code con IS DISTINCT FROM — re-ejecutar no escribe nada.
-- No inserta ni borra filas; solo actualiza description de códigos existentes.
-- Cobertura: 1235 partidas, 5619 subpartidas. Quedan como
-- placeholder 13 subpartidas legacy pre-HS2022 (080300, 340220, 380810, 380820,
-- 380830, 441871, 610430, 620112, 620212, 841310, 852580, 852851, 853950) que NO
-- existen en la TIGIE 2026 — residuo del seed legacy tigie-data.ts, documentado.

UPDATE "headings" AS h
SET "description" = v.descripcion
FROM (VALUES
  ('0101', 'Caballos, asnos, mulos y burdéganos, vivos.'),
